  static bool isRegistered(IconData? icon) => _material.containsKey(icon);

  static AppIconId fromMaterial(IconData? icon) {
    final id = _material[icon];
    if (id == null) {
      throw ArgumentError.value(icon, 'icon', 'Unregistered command icon');
    }
    return id;
  }
